SELECT DATE(done_at) AS day, COALESCE(SUM(sum_fee), 0) AS fee, COALESCE(SUM(dust), 0) AS dust, COUNT(*) AS n FROM settle_run
WHERE kind = 'PAYOUT' AND status = 'DONE' AND done_at >= #{from} AND done_at < #{to}
GROUP BY DATE(done_at) ORDER BY day

SELECT DATE(created_at) AS day, SUM(total_amount) AS amount, COUNT(*) AS n FROM settle_compensation
WHERE created_at >= #{from} AND created_at < #{to}
GROUP BY DATE(created_at) ORDER BY day
